   style
    body 
      font-family: roboto, verdana, sans-serif;
      font-weight: 400;
      color: #5a5a5a;      
      margin: 0;

    body a 
      text-decoration: none;
      color: #629c2e;

    body a:hover 
      text-decoration: underline;

    #app 
      display: flex;
      flex-direction: column;
      min-height: 99.8vh;      

    #top-chrome 
      display: flex;
      justify-content: space-between;
      font-weight: 400;
      position: fixed;
      background: #fff;
      width: 100%;
      z-index: 1100;
      border-bottom: 1px solid #f3f3f3;
      box-shadow: 0 3px 7px #dfdfdf;
      height: 4rem;

    #logo-etc 
      position: relative;
      display: flex;
      align-items: center;      

    #logo 
      height: 85%;

    #logo img 
      height: 100%

    #logo a 
      cursor: pointer;
      text-decoration: none;

    #menu-controls ul 
      list-style: none;
      text-align: center;
      padding: 0;
      margin: 0;
      display: flex;      

    #menu-controls li 
      font-size: 1rem;
      font-weight: 400;
      height: 65px;
      text-align: left;
      border-bottom: none;
      border-left: 1px solid #ddd;
      line-height: 65px;
      margin: 0;
      padding: 0;
      box-sizing: border-box;
      display: flex;
      position: relative;
      white-space: nowrap;

    #menu-controls a 
      text-decoration: none;
      border-bottom: 0;
      transition: background-color .3s;
      padding: 0 .65rem;
      margin: 0;
      height: 100%;
      cursor: pointer;
      color: #629c2e;      

    #menu-controls a:hover 
      color: #fff;
      background: #629c2e;

    main#content 
      flex: 1;
      margin: 5rem 0 0;
      display: flex; 
      flex-direction: column; 
      align-items: center; 
      justify-content: center; 

    .home-body 
      * 70vw wide, never narrower than 60rem -- unless the screen itself is narrower *
      width: max(70vw, min(60rem, calc(100% - 2rem)));
      margin: 0 auto;
      box-sizing: border-box;

    .announcement 
      font-size: 150%; 
      border: 3px solid rgb(253, 186, 77);
      border-radius: 5px; 
      padding: 0px 25px; 
      margin: 0 0 2rem;
      text-align: center;

    .bold 
      font-style: normal;
      font-weight: 900;

    #footer 
      font-size: .75rem;
      font-weight: 300;
      bottom: 0;
      height: 3.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0;      

    #footer-links 
      list-style-type: none;
      padding: 0;
      margin: 0 0 0 1em;      

    #footer-links li 
      display: inline;
      padding-right: 1rem;      

    #footer-links a 
      text-decoration: none;
      color: #629c2e;      

    #doe-office-of-science 
      margin: .25rem 1rem 0 0;

    * Narrow screens: the logo plus three nowrap menu items need ~50rem, so stack them *
    @media (max-width: 52rem) 
      #top-chrome 
        position: static;
        height: auto;
        flex-direction: column;

      #logo 
        height: auto;
        padding: .5rem 1rem;

      #logo img 
        display: block;
        height: auto;
        width: 100%;
        max-width: 20rem;

      #menu-controls ul 
        flex-wrap: wrap;
        border-top: 1px solid #ddd;

      #menu-controls li 
        flex: 1 1 auto;
        height: 2.75rem;
        line-height: 2.75rem;
        font-size: .9rem;

      #menu-controls li:first-child 
        border-left: none;

      #menu-controls a 
        flex: 1;
        text-align: center;

      main#content 
        margin-top: 1.5rem;

      .announcement 
        font-size: 125%;
        padding: 0 1rem;

      #footer 
        height: auto;
        flex-direction: column;
        align-items: flex-start;
        padding: 1rem 0;

      #footer-links li 
        display: inline-block;
        padding-bottom: .5rem;

      #doe-office-of-science 
        margin: .5rem 0 0 1em;


